content.text:
  function setStep(next, shouldScroll) {
    step = Math.max(0, Math.min(STEP_COUNT - 1, next));
    render();
    if (shouldScroll) {
      scrollWizardTop();
      centerActiveTab();
      announce('Шаг ' + (step + 1) + ' из ' + STEP_COUNT + '.');
    }
  }

  /* ---------- подсчёт баллов ---------- */
  function computeScore() {
    var score = { d: 0, i: 0, s: 0, c: 0 };
    toArray(panesEl.querySelectorAll('.disc-list')).forEach(function (list) {
      var items = listItems(list);
      if (items.length !== ITEMS_PER_LIST) return;
      score[items[0].dataset.type] += 1;
      score[items[ITEMS_PER_LIST - 1].dataset.type] -= 1;
    });
    return score;
  }

  function renderResult() {
    var score = computeScore();

    scoreLine.textContent =
      'D:' + score.d + ', I:' + score.i + ', S:' + score.s + ', C:' + score.c;

    ['d', 'i', 's', 'c'].forEach(function (type) {
      var row = document.querySelector('.scale[data-type="' + type + '"]');
      if (!row) return;
      var value = score[type];
      var fill = row.querySelector('.scale__fill');
      var val = row.querySelector('.scale__val');
      var width = Math.min(Math.abs(value) / MAX_SCORE, 1) * 50;

      val.textContent = String(value);
      fill.style.width = width + '%';
      if (value < 0) {
        fill.style.right = '50%';
        fill.style.left = 'auto';
        row.classList.add('is-neg');
      } else {
        fill.style.left = '50%';
        fill.style.right = 'auto';
        row.classList.remove('is-neg');
      }
    });
  }

  /* ---------- перетаскивание (Pointer Events: мышь, палец, стилус) ---------- */
  var drag = null;

  function beginDrag(event, item) {
    var list = item.parentNode;
    var onHandle = !!(event.target.closest && event.target.closest('.item__handle'));

    if (event.pointerType !== 'mouse' && !onHandle) return;
    if (event.pointerType === 'mouse' && event.button !== 0) return;

    event.preventDefault();

    drag = {
      item: item,
      list: list,
      pointerId: event.pointerId,
      startY: event.clientY,
      moved: false
    };

    item.classList.add('is-dragging');
    list.classList.add('is-sorting');
    document.body.classList.add('is-dragging-active');

    if (document.activeElement !== item && typeof item.focus === 'function') {
      item.focus({ preventScroll: true });
    }
  }

  function autoscroll(y) {
    var edge = 84;
    var speed = 16;
    var height = window.innerHeight;

    if (y < edge) {
      window.scrollBy(0, -Math.ceil(speed * (1 - y / edge)));
    } else if (y > height - edge) {
      window.scrollBy(0, Math.ceil(speed * (1 - (height - y) / edge)));
    }
  }

  function moveDrag(y) {
    if (!drag) return;
    var list = drag.list;
    var siblings = listItems(list).filter(function (node) {
      return node !== drag.item;
    });

    var target = null;
    for (var i = 0; i < siblings.length; i++) {
      var rect = siblings[i].getBoundingClientRect();
      if (y < rect.top + rect.height / 2) {
        target = siblings[i];
        break;
      }
    }

    if (target) {
      if (drag.item.nextElementSibling !== target) list.insertBefore(drag.item, target);
    } else if (list.lastElementChild !== drag.item) {
      list.appendChild(drag.item);
    }
  }

  function endDrag() {
    if (!drag) return;
    var current = drag;
    drag = null;

    current.item.classList.remove('is-dragging');
    current.list.classList.remove('is-sorting');
    document.body.classList.remove('is-dragging-active');
    refreshPositions(current.list);

    var items = listItems(current.list);
    var index = items.indexOf(current.item);
    var word = current.item.querySelector('.item__word');
    announce('«' + (word ? word.textContent : '') + '» теперь на позиции ' + (index + 1) + ' из ' + items.length + '.');
  }

  function onPointerDown(event) {
    var item = event.target.closest && event.target.closest('.item');
    if (!item || !panesEl.contains(item)) return;
    beginDrag(event, item);
  }

  function onPointerMove(event) {
    if (!drag || event.pointerId !== drag.pointerId) return;
    if (!drag.moved && Math.abs(event.clientY - drag.startY) < 3) return;
    drag.moved = true;
    event.preventDefault();
    moveDrag(event.clientY);
    autoscroll(event.clientY);
  }

  function onPointerUp(event) {
    if (!drag) return;
    if (event && event.pointerId !== undefined && event.pointerId !== drag.pointerId) return;
    endDrag();
  }

  /* ---------- клавиатура: ↑ / ↓ / Home / End ---------- */
  function onKeyDown(event) {
    var item = event.target.closest && event.target.closest('.item');
    if (!item || !panesEl.contains(item)) return;

    var items = listItems(item.parentNode);
    var index = items.indexOf(item);
    var target = null;
    var isMove = false;

    if (event.key === 'ArrowUp' || event.key === 'ArrowLeft') {
      if (index > 0) { target = items[index - 1]; isMove = true; item.parentNode.insertBefore(item, target); }
    } else if (event.key === 'ArrowDown' || event.key === 'ArrowRight') {
      if (index < items.length - 1) { target = items[index + 1]; isMove = true; item.parentNode.insertBefore(target, item); }
    } else if (event.key === 'Home') {
      if (index > 0) { target = items[0]; isMove = true; item.parentNode.insertBefore(item, items[0]); }
    } else if (event.key === 'End') {
      if (index < items.length - 1) { isMove = true; item.parentNode.appendChild(item); }
    }

    if (!isMove) return;

    event.preventDefault();
    refreshPositions(item.parentNode);
    item.focus({ preventScroll: true });
    if (typeof item.scrollIntoView === 'function') item.scrollIntoView({ block: 'nearest' });

    var newIndex = listItems(item.parentNode).indexOf(item);
    var word = item.querySelector('.item__word');
    announce('«' + (word ? word.textContent : '') + '» теперь на позиции ' + (newIndex + 1) + ' из ' + items.length + '.');
  }

  /* ---------- сценарии ---------- */
  function startTest() {
    resetWizard();
    step = 0;
    render();
    showScreen('test');
    centerActiveTab();
    announce('Тест начат. Шаг 1 из 8.');
  }

  function finishTest() {
    renderResult();
    showScreen('result');
    announce('Тест завершён. ' + scoreLine.textContent);
  }

  /* ---------- события ---------- */
  btnStart.addEventListener('click', startTest);
  btnRestart.addEventListener('click', startTest);
  btnRestartTop.addEventListener('click', startTest);

  btnPrev.addEventListener('click', function () { setStep(step - 1, true); });
  btnNext.addEventListener('click', function () { setStep(step + 1, true); });
  btnFinish.addEventListener('click', finishTest);

  btnFine.addEventListener('click', function () {
    showScreen('test');
    setStep(STEP_COUNT - 1, true);
    window.scrollTo(0, 0);
  });

  tabsEl.addEventListener('click', function (event) {
    var tab = event.target.closest('.tab');
    if (!tab) return;
    setStep(Number(tab.dataset.step), true);
  });

  tabsEl.addEventListener('keydown', function (event) {
    if (event.key !== 'ArrowLeft' && event.key !== 'ArrowRight') return;
    event.preventDefault();
    var delta = event.key === 'ArrowRight' ? 1 : -1;
    var next = Math.min(STEP_COUNT - 1, Math.max(0, step + delta));
    setStep(next, true);
    var tab = tabsEl.children[next];
    if (tab) tab.focus({ preventScroll: true });
  });

  panesEl.addEventListener('pointerdown', onPointerDown);
  panesEl.addEventListener('keydown', onKeyDown);
  window.addEventListener('pointermove', onPointerMove, { passive: false });
  window.addEventListener('pointerup', onPointerUp);
  window.addEventListener('pointercancel', onPointerUp);

  window.addEventListener('blur', endDrag);

  /* ---------- инициализация ---------- */
  resetWizard();
  render();
  showScreen('intro');
})();
</script>
</body>
</html>

